`timescale 1ns / 1ps

module tb_md5_multiple_blocks;

    reg clk;
    reg reset;
    reg [511:0] chunk;
    wire [31:0] a64, b64, c64, d64;

    Md5Core u_md5 (
        .clk(clk),
        .wb(chunk),
        .a0(32'h67452301),
        .b0(32'hefcdab89),
        .c0(32'h98badcfe),
        .d0(32'h10325476),
        .a64(a64),
        .b64(b64),
        .c64(c64),
        .d64(d64)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    reg [1:0] msg_sel;

    initial begin
        $dumpfile("md5_multiple_blocks.vcd");
        $dumpvars(0, tb_md5_multiple_blocks);

        reset = 1;
        chunk = 512'b0;
        msg_sel = 0;
        #20;
        reset = 0;
        #10;

        repeat (20) begin
            case (msg_sel)
                0: chunk = 512';  // empty string
                1: chunk = 512';  // "A"
                2: chunk = 512';  // "AAA"
            endcase
            #650;
            msg_sel = msg_sel + 1;
        end

        #1000;
        $finish;
    end

endmodule